76	    /// Helper method to get the next index name from the enumerator with a try catch around the move next call to convert
77	    /// any <see cref="RequestFailedException"/> to <see cref="HttpOperationException"/>, since try catch is not supported
78	    /// around a yield return.
79	    /// </summary>
80	    /// <param name="enumerator">The enumerator to get the next result from.</param>
81	    /// <returns>A value indicating whether there are more results and the current string if true.</returns>
82	    private static async Task<(string name, bool more)> GetNextIndexNameAsync(ConfiguredCancelableAsyncEnumerable<string>.Enumerator enumerator)
83	    {
84	        const string OperationName = "GetIndexNames";
85	
86	        try
87	        {
88	            var more = await enumerator.MoveNextAsync();
89	            return (enumerator.Current, more);
90	        }
91	        catch (AggregateException ex) when (ex.InnerException is RequestFailedException innerEx)
92	        {
93	            throw new VectorStoreOperationException("Call to vector store failed.", ex)
94	            {
95	                VectorStoreType = DatabaseName,
96	                OperationName = OperationName
97	            };
98	        }
99	        catch (RequestFailedException ex)
100	        {
101	            throw new VectorStoreOperationException("Call to vector store failed.", ex)
102	            {
103	                VectorStoreType = DatabaseName,
104	                OperationName = OperationName
105	            };
106	        }
107	    }
108	}
